    flips = []
    for i in range(5):
        if input_1mod3[i] != output_1mod3[i]:
            flips.append(i)

    print(f"Row {r}: input={input_1mod3}, output={output_1mod3}, flip_indices={flips}")

    # Does output = input with flipped bits at flip_indices?
    reconstructed = list(input_1mod3)
    for fi in flips:
        if reconstructed[fi] == 6:
            reconstructed[fi] = 0
        else:
            reconstructed[fi] = 6

    print(f"  Reconstructed: {reconstructed}, matches output: {reconstructed == output_1mod3}")

